const axios = require("axios")
const { parseFileSize, getFileSize } = require("../../utils/filesize")

const delay = (ms) => new Promise(resolve => setTimeout(resolve, ms))

/* convertir cualquier link de youtube a youtu.be */
function normalizeYT(url) {
    try {

        let u = new URL(url)

        if (u.hostname.includes("youtu.be")) {
            return url
        }

        if (u.hostname.includes("youtube.com")) {

            if (u.pathname.includes("/watch")) {
                let id = u.searchParams.get("v")
                if (id) return `https://youtu.be/${id}`
            }

            if (u.pathname.includes("/shorts/")) {
                let id = u.pathname.split("/shorts/")[1]
                return `https://youtu.be/${id}`
            }

            if (u.pathname.includes("/embed/")) {
                let id = u.pathname.split("/embed/")[1]
                return `https://youtu.be/${id}`
            }
        }

        return url

    } catch {
        return url
    }
}

async function ytmp3(url, calidad = "128k") {

    url = normalizeYT(url)

    const { data } = await axios.post(
        "https://app.ytdown.to/proxy.php",
        new URLSearchParams({ url }).toString(),
        {
            headers: { "Content-Type": "application/x-www-form-urlencoded" },
            timeout: 20000
        }
    )

    const api = data?.api

    if (!api) throw "❌ No se pudo obtener información del video"
    if (api.status === "ERROR") throw api.message

    let media = api.mediaItems || []

    let qualities = media.map((v, i) => {

        let match = v?.mediaUrl?.match(/(\d+)p|(\d+)k/)
        let res = match ? match[0] : v.mediaQuality

        return {
            id: i + 1,
            type: v.type,
            quality: res,
            label: `${v.mediaExtension?.toUpperCase()} - ${v.mediaQuality}`,
            size: v.mediaFileSize,
            mediaUrl: v.mediaUrl,
            duration: v.mediaDuration
        }
    })

    if (calidad) {

        calidad = calidad.toLowerCase()

        let selected = qualities.find(v =>
            v.quality && v.quality.toLowerCase() === calidad
        )

        if (!selected) {

            let disponibles = qualities
                .filter(v => v.quality)
                .map(v => v.quality)
                .join(", ")

            throw `❌ Calidad ${calidad} no disponible\nDisponibles: ${disponibles}`
        }

        let direct = await download(selected.mediaUrl)

        return {
            title: api.title,
            thumb: api.imagePreviewUrl,
            id: selected.id,
            duration: selected.duration,
            quality: selected.quality,
            size: selected.size,
            sizeB: parseFileSize(selected.size),
            dl_url: direct
        }
    }

    return {
        title: api.title,
        uploader: api.userInfo?.name,
        views: api.mediaStats?.viewsCount,
        thumbnail: api.imagePreviewUrl,
        qualities
    }
}

async function download(mediaUrl) {

    let attempts = 0

    while (attempts < 15) {

        try {

            let { data } = await axios.get(mediaUrl, { timeout: 15000 })

            if (
                data?.percent === "Completed" &&
                data?.fileUrl &&
                data.fileUrl !== "In Processing..."
            ) {
                return data.fileUrl
            }

        } catch {}

        attempts++
        await delay(4000)
    }

    throw "❌ No se pudo generar el enlace de descarga"
}




///----


let jsonCache = null

const gB = Buffer.from('ZXRhY2xvdWQub3Jn','base64').toString()

const headers = {
  origin: 'https://v1.y2mate.nu',
  referer: 'https://v1.y2mate.nu/',
  'user-agent':
    'Mozilla/5.0 (Linux; Android 10) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/139.0.0.0 Mobile Safari/537.36'
}

const sleep = ms => new Promise(r => setTimeout(r, ms))
const ts = () => Math.floor(Date.now() / 1000)

// ===== GET CONFIG =====
async function getjson() {
  if (jsonCache) return jsonCache

  const get = await axios.get('https://v1.y2mate.nu')
  const match = /var json = JSON\.parse\('([^']+)'\)/.exec(get.data)

  if (!match) throw new Error('No se pudo obtener config')

  jsonCache = JSON.parse(match[1])
  return jsonCache
}

// ===== AUTH =====
function authorization(json) {
  let e = ''

  for (let i = 0; i < json[0].length; i++) {
    e += String.fromCharCode(
      json[0][i] - json[2][json[2].length - (i + 1)]
    )
  }

  if (json[1]) e = e.split('').reverse().join('')

  return e.length > 32 ? e.slice(0, 32) : e
}

// ===== INIT =====
async function init(json) {
  const key = String.fromCharCode(json[6])

  const url = `https://eta.${gB}/api/v1/init?${key}=${authorization(json)}&t=${ts()}`

  const res = await axios.get(url, { headers })

  if (res.data.error != 0)
    throw new Error('Error iniciando API')

  return res.data
}

// ===== MAIN =====
async function yt2mate(input, format = 'mp3') {
  let videoId = input

  // Detectar ID si es URL
  if (/youtu/.test(input)) {
    videoId = input.match(
      /(?:youtube\.com\/(?:watch\?v=|embed\/|shorts\/)|youtu\.be\/)([A-Za-z0-9_-]{11})/
    )?.[1]

    if (!videoId) throw new Error('No se pudo extraer ID')
  }

  const json = await getjson()
  const initRes = await init(json)

  let res = await axios.get(
    `${initRes.convertURL}&v=${videoId}&f=${format}&t=${ts()}&_=${Math.random()}`,
    { headers }
  )

  let data = res.data

  if (data.error != 0)
    throw new Error('Error convirtiendo')

  // Manejo de redirect
  if (data.redirect === 1 && data.redirectURL) {
    const r2 = await axios.get(
      data.redirectURL + '&t=' + ts(),
      { headers }
    )
    data = r2.data
  }

  // Esperar procesamiento
  for (let i = 0; i < 25; i++) {

  // ✅ Si ya hay link directo
  if (data.downloadURL) {
    const size = await getFileSize(data.downloadURL)

    return {
      title: data.title,
      size,
      sizeB: parseFileSize(size),
      dl_url: data.downloadURL
    }
  }

  // ⏳ esperar
  await sleep(2500)

  if (!data.progressURL) break

  try {
    const progress = await axios.get(
      data.progressURL + '&t=' + ts(),
      { headers }
    )

    data = progress.data

    // 🔥 A veces NO manda progress=3 pero sí downloadURL
    if (data.downloadURL) {
      const size = await getFileSize(data.downloadURL)

      return {
        title: data.title,
        size,
        sizeB: parseFileSize(size),
        dl_url: data.downloadURL
      }
    }

  } catch (e) {
    // ⚠ ignorar errores temporales
  }
}

  throw new Error('Timeout procesando audio')
}

//----
async function yta(url) {

    // normalizar siempre
    url = normalizeYT(url)

    try {
        // ===== ENGINE 1 (YTA) =====
        const res = await ytmp3(url, "128k")

        return {
            title: res.title,
            thumb: res.thumb,
            id: res.id,
            duration: res.duration,
            quality: res.quality,
            size: res.size,
            sizeB: res.sizeB,
            dl_url: res.dl_url
        }

    } catch (e) {

        // ===== ENGINE 2 (YT2MATE) =====
        const res = await yt2mate(url)

        return {
            title: res.title,
            thumb: null,           // ❌ no lo da yt2mate
            id: null,
            duration: null,
            quality: "128k",
            size: res.size,
            sizeB: res.sizeB,
            dl_url: res.dl_url
        }
    }
}

module.exports = { yta }